/* global d3 */

const chartWidth = 700;
const chartHeight = 520;
const chartMargin = { top: 16, right: 16, bottom: 16, left: 16 };

const svg = d3
  .select("#bubble-chart")
  .attr("viewBox", `0 0 ${chartWidth} ${chartHeight}`)
  .attr("preserveAspectRatio", "xMidYMid meet");

const tooltip = d3.select("#tooltip");

const formatNumber = d3.format(".2f");

function trimNumber(value) {
  return value.replace(/\.00$/, "").replace(/(\.\d)0$/, "$1");
}

function formatMarketCap(value) {
  if (!value || Number.isNaN(value)) {
    return "—";
  }
  const abs = Math.abs(value);
  if (abs >= 1e12) {
    return `${trimNumber(formatNumber(value / 1e12))}T`;
  }
  if (abs >= 1e9) {
    return `${trimNumber(formatNumber(value / 1e9))}B`;
  }
  if (abs >= 1e6) {
    return `${trimNumber(formatNumber(value / 1e6))}M`;
  }
  if (abs >= 1e3) {
    return `${trimNumber(formatNumber(value / 1e3))}K`;
  }
  return value.toFixed(0);
}

function buildVisualization(data) {
  const cleaned = data
    .map((d) => ({
      ticker: d.ticker,
      sector: d.sector,
      fullName: d["full name"],
      marketCap: d.marketCap ? +d.marketCap : null,
      country: d.country,
      website: d.website,
    }))
    .sort((a, b) => d3.ascending(a.ticker, b.ticker));

  const sectors = Array.from(new Set(cleaned.map((d) => d.sector))).sort(
    d3.ascending
  );

  const color = d3.scaleOrdinal(sectors, d3.schemeTableau10);

  const marketCaps = cleaned
    .map((d) => d.marketCap)
    .filter((d) => d !== null && !Number.isNaN(d));

  const minCap = d3.min(marketCaps);
  const maxCap = d3.max(marketCaps);

  const radiusScale = d3
    .scaleSqrt()
    .domain([minCap, maxCap])
    .range([14, 46]);

  const etfRadius = 14;

  const centerX = chartWidth / 2;
  const centerY = chartHeight / 2;
  const clusterRadius = Math.min(chartWidth, chartHeight) * 0.23;

  const sectorCenters = new Map();
  const angleStep = (Math.PI * 2) / sectors.length;

  sectors.forEach((sector, index) => {
    const angle = index * angleStep - Math.PI / 2;
    sectorCenters.set(sector, {
      x: centerX + clusterRadius * Math.cos(angle),
      y: centerY + clusterRadius * Math.sin(angle),
    });
  });

  const nodes = cleaned.map((d) => {
    const radius = d.marketCap ? radiusScale(d.marketCap) : etfRadius;
    return {
      ...d,
      r: radius,
      isEtf: !d.marketCap,
      x: 0,
      y: 0,
    };
  });

  sectors.forEach((sector) => {
    const items = nodes
      .filter((d) => d.sector === sector)
      .sort((a, b) => d3.ascending(a.ticker, b.ticker));
    const cols = Math.ceil(Math.sqrt(items.length));
    const rows = Math.ceil(items.length / cols);
    const spacing = 10;
    const base = sectorCenters.get(sector);

    items.forEach((d, index) => {
      const col = index % cols;
      const row = Math.floor(index / cols);
      const offsetX = (col - (cols - 1) / 2) * spacing;
      const offsetY = (row - (rows - 1) / 2) * spacing;
      d.x = base.x + offsetX;
      d.y = base.y + offsetY;
    });
  });

  const rng = d3.randomLcg(0.42);

  const simulation = d3
    .forceSimulation(nodes)
    .randomSource(rng)
    .force(
      "x",
      d3
        .forceX((d) => sectorCenters.get(d.sector).x)
        .strength(0.08)
    )
    .force(
      "y",
      d3
        .forceY((d) => sectorCenters.get(d.sector).y)
        .strength(0.08)
    )
    .force("collide", d3.forceCollide((d) => d.r + 1).iterations(2))
    .stop();

  for (let i = 0; i < 280; i += 1) {
    simulation.tick();
  }

  const nodeGroup = svg.append("g").attr("class", "nodes");

  const node = nodeGroup
    .selectAll("g")
    .data(nodes, (d) => d.ticker)
    .join("g")
    .attr("class", "bubble")
    .attr("transform", (d) => `translate(${d.x},${d.y})`);

  node
    .append("circle")
    .attr("r", (d) => d.r)
    .attr("fill", (d) => color(d.sector))
    .attr("opacity", 0.9)
    .attr("stroke", "#1a1a1a")
    .attr("stroke-width", 0.6);

  node
    .append("text")
    .text((d) => d.ticker)
    .attr("text-anchor", "middle")
    .attr("dy", "0.35em")
    .attr("fill", "#ffffff")
    .attr("font-weight", 600)
    .attr("font-size", (d) => Math.max(8, Math.min(14, d.r * 0.6)))
    .attr("pointer-events", "none");

  node
    .on("mouseover", (event, d) => {
      if (d.isEtf) {
        return;
      }
      tooltip
        .classed("visible", true)
        .html(
          `<strong>${d.ticker}</strong><br/>${d.fullName}<br/>Sector: ${d.sector}`
        )
        .style("left", `${event.pageX + 12}px`)
        .style("top", `${event.pageY - 28}px`);
    })
    .on("mousemove", (event, d) => {
      if (d.isEtf) {
        return;
      }
      tooltip
        .style("left", `${event.pageX + 12}px`)
        .style("top", `${event.pageY - 28}px`);
    })
    .on("mouseout", () => {
      tooltip.classed("visible", false);
    });

  const legend = svg.append("g").attr("class", "legend");

  const legendItem = legend
    .selectAll("g")
    .data(sectors)
    .join("g")
    .attr("transform", (d, i) => `translate(${chartWidth - 160},${24 + i * 20})`);

  legendItem
    .append("circle")
    .attr("r", 6)
    .attr("cx", 0)
    .attr("cy", 0)
    .attr("fill", (d) => color(d));

  legendItem
    .append("text")
    .attr("x", 12)
    .attr("y", 4)
    .text((d) => d);

  const tableBody = d3.select("#stock-table tbody");

  const rows = tableBody
    .selectAll("tr")
    .data(cleaned, (d) => d.ticker)
    .join("tr");

  rows
    .append("td")
    .text((d) => d.ticker);

  rows
    .append("td")
    .text((d) => d.fullName);

  rows
    .append("td")
    .text((d) => d.sector);

  rows
    .append("td")
    .text((d) => formatMarketCap(d.marketCap));

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker;
    node.classed("selected", (d) => d.ticker === selectedTicker);
    rows.classed("selected", (d) => d.ticker === selectedTicker);
  }

  node.on("click", (event, d) => {
    const nextTicker = selectedTicker === d.ticker ? null : d.ticker;
    setSelected(nextTicker);
  });

  rows.on("click", (event, d) => {
    const nextTicker = selectedTicker === d.ticker ? null : d.ticker;
    setSelected(nextTicker);
  });
}

d3.csv("data/stock-descriptions.csv").then(buildVisualization);
